"""
Patch the base64-embedded TTF in every resources/*/style.css so the shipped
font has correct glyph bboxes. Removes the Firefox warning:

    downloadable font: glyf: Glyph bbox was incorrect; adjusting (glyph N)

Run from the repo root:

    py -3 tools\\fix_glyf_bbox.py
    py -3 tools\\fix_glyf_bbox.py --verbose
    py -3 tools\\fix_glyf_bbox.py --self-test

The default run is idempotent: running it again on a clean font prints
"0 glyph(s) patched". Wired into gulpfile.js via the `fix-glyf-bbox`
task, so `npm run compile` runs it automatically.
"""
import base64
import os
import re
import sys
import tempfile

from fontTools.ttLib import TTFont
from fontTools.ttLib.tables._g_l_y_f import Glyph as TTGlyph

URL_RE = re.compile(
    r"url\(data:application/x-font-ttf;charset=utf-8;base64,([A-Za-z0-9+/=]+)\) format\('truetype'\);"
)


# ---------------------------------------------------------------------------
# Core: recompute glyph bboxes from raw contour coordinates
# ---------------------------------------------------------------------------

def _true_bounds(glyph, glyf_table):
    """Return (xMin, yMin, xMax, yMax) from raw contour coords, or None.

    Reads the actual contour coordinates from the glyf table — not via
    getGlyphSet, which applies a bbox-relative transform that masks the
    real outline extent. Composite glyphs (numberOfContours == -1) are
    handled by recursing through their components and applying each
    component's 2x2 transform.
    """
    if glyph is None or glyph.numberOfContours is None or glyph.numberOfContours == 0:
        return None
    if glyph.numberOfContours > 0 and glyph.coordinates:
        xs = [p[0] for p in glyph.coordinates]
        ys = [p[1] for p in glyph.coordinates]
        return (min(xs), min(ys), max(xs), max(ys))
    if glyph.numberOfContours == -1:
        xs, ys = [], []
        for comp in glyph.components:
            sub = glyf_table[comp.glyphName]
            sub_bounds = _true_bounds(sub, glyf_table)
            if sub_bounds is None:
                continue
            a, b, c, d, e, f = comp.transform
            sx, sy, smx, smy, _, _ = sub_bounds
            corners = [(sx, sy), (smx, sy), (sx, smy), (smx, smy)]
            xs.extend(a * x + c * y + e for x, y in corners)
            ys.extend(b * x + d * y + f for x, y in corners)
        if not xs:
            return None
        return (min(xs), min(ys), max(xs), max(ys))
    return None


def _fix_ttf(src_path, dst_path, verbose=False):
    """Rewrite every glyph bbox + head.fontBbox.

    Returns (n_glyphs_patched, head_patched_bool_or_tuple).
    Only changes bbox metadata in the glyf/head tables; outline
    coordinates, advance widths, cmap, names — everything else — is
    untouched.
    """
    font = TTFont(src_path)
    glyf_table = font["glyf"]
    fixed_glyphs = 0
    fixed_log = []
    for gname in glyf_table.keys():
        g = glyf_table[gname]
        b = _true_bounds(g, glyf_table)
        if b is None:
            continue
        old = (g.xMin, g.yMin, g.xMax, g.yMax)
        if old != b:
            fixed_glyphs += 1
            fixed_log.append((gname, old, b))
            g.xMin, g.yMin, g.xMax, g.yMax = b

    xs, ys = [], []
    for gname in glyf_table.keys():
        b = _true_bounds(glyf_table[gname], glyf_table)
        if b is None:
            continue
        xs.append((b[0], b[2]))
        ys.append((b[1], b[3]))
    head_patched = False
    if xs:
        head = font["head"]
        new_head = (min(p[0] for p in xs), min(p[1] for p in ys),
                    max(p[0] for p in xs), max(p[1] for p in ys))
        old_head = (head.xMin, head.yMin, head.xMax, head.yMax)
        if old_head != new_head:
            head.xMin, head.yMin, head.xMax, head.yMax = new_head
            head_patched = (old_head, new_head)

    if verbose:
        for gname, old, new in fixed_log:
            print(f"  {gname:<24}  {old}  ->  {new}")
        if head_patched:
            print(f"  head.fontBbox  {head_patched[0]}  ->  {head_patched[1]}")

    font.save(dst_path)
    return fixed_glyphs, head_patched


# ---------------------------------------------------------------------------
# Driver: patch the embedded TTF inside one style.css
# ---------------------------------------------------------------------------

def _fix_style_css(theme_dir, verbose=False):
    """Return (n_glyphs, head_patched) or (None, None) if no TTF found."""
    css_path = os.path.join(theme_dir, "style.css")
    with open(css_path, "r", encoding="utf-8") as f:
        css = f.read()
    m = URL_RE.search(css)
    if not m:
        return None, None
    raw = base64.b64decode(m.group(1))
    src = tempfile.NamedTemporaryFile(suffix=".ttf", delete=False)
    src.write(raw)
    src.close()
    fixed_path = src.name + ".fixed.ttf"
    n_glyphs, head_patched = _fix_ttf(src.name, fixed_path, verbose=verbose)
    with open(fixed_path, "rb") as f:
        new_b64 = base64.b64encode(f.read()).decode("ascii")
    new_url = ("url(data:application/x-font-ttf;charset=utf-8;base64,"
               + new_b64 + ") format('truetype');")
    new_css, k = URL_RE.subn(new_url, css, count=1)
    if k != 1:
        os.remove(src.name); os.remove(fixed_path)
        raise RuntimeError(f"could not replace url() in {css_path}")
    with open(css_path, "w", encoding="utf-8", newline="") as f:
        f.write(new_css)
    os.remove(src.name); os.remove(fixed_path)
    return n_glyphs, head_patched


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------

def _iter_themes(resources):
    for name in sorted(os.listdir(resources)):
        if os.path.isfile(os.path.join(resources, name, "style.css")):
            yield name


def main():
    if "--self-test" in sys.argv:
        return _self_test()
    verbose = "--verbose" in sys.argv

    here = os.path.dirname(os.path.abspath(__file__))
    resources = os.path.abspath(os.path.join(here, "..", "resources"))
    if not os.path.isdir(resources):
        print(f"resources/ not found at {resources}", file=sys.stderr)
        sys.exit(2)
    themes = list(_iter_themes(resources))
    if not verbose:
        print(f"Scanning {len(themes)} theme(s)…")
    total_files, total_glyphs = 0, 0
    for t in themes:
        theme_dir = os.path.join(resources, t)
        try:
            n_glyphs, head_patched = _fix_style_css(theme_dir, verbose=verbose)
        except Exception as ex:
            print(f"  [error] {t}: {ex}", file=sys.stderr)
            sys.exit(1)
        if n_glyphs is None:
            if verbose:
                print(f"[skip] {t:<14} (no embedded TTF)")
            continue
        if n_glyphs > 0 or head_patched:
            total_files += 1
            total_glyphs += n_glyphs
            if verbose:
                print(f"[ok]   {t:<14} patched {n_glyphs} glyph(s)"
                      + (", head.fontBbox" if head_patched else ""))
            else:
                print(f"[fix]  {t:<14} {n_glyphs} glyph(s)"
                      + (", +head.fontBbox" if head_patched else ""))
        else:
            if verbose:
                print(f"[clean]{t:<14} no changes needed")
    print(f"\n{total_files}/{len(themes)} theme(s) updated, "
          f"{total_glyphs} glyph(s) patched.")


def _self_test():
    """Round-trip a tiny TTF with corrupted bbox; verify it gets fixed."""
    src = os.path.join(tempfile.gettempdir(), "_gf_self_in.ttf")
    dst = os.path.join(tempfile.gettempdir(), "_gf_self_out.ttf")

    from fontTools.fontBuilder import FontBuilder
    fb = FontBuilder(1024, isTTF=True)
    fb.setupGlyphOrder([".notdef", "tri"])
    fb.setupCharacterMap({0xE700: "tri"})
    fb.setupGlyf({
        ".notdef": {"numberOfContours": 0},
        "tri": {
            "numberOfContours": 1,
            "coordinates": [(100, 100), (924, 100), (512, 924)],
            "flags": [1, 1, 1],
            "endPtsOfContours": [2],
        },
    })
    fb.setupHorizontalMetrics({"tri": (1024, 100), ".notdef": (1024, 0)})
    fb.setupHorizontalHeader(ascent=924, descent=-100)
    fb.setupNameTable({"familyName": "TEST", "styleName": "Regular"})
    fb.setupOs2(sTypoAscender=924, sTypoDescender=-100,
                usWinAscent=924, usWinDescent=100)
    fb.setupPost()
    fb.setupHead(unitsPerEm=1024)
    fb.font.save(src)

    bad = TTFont(src)
    bad["glyf"]["tri"].xMin = 0
    bad["glyf"]["tri"].yMin = 0
    bad["glyf"]["tri"].xMax = 200
    bad["glyf"]["tri"].yMax = 200
    bad["head"].xMin = 0; bad["head"].yMin = 0
    bad["head"].xMax = 200; bad["head"].yMax = 200
    bad.save(src)

    n, head = _fix_ttf(src, dst, verbose=True)
    out = TTFont(dst)
    g = out["glyf"]["tri"]
    asserts = [
        ("tri.xMin",    g.xMin,    100),
        ("tri.yMin",    g.yMin,    100),
        ("tri.xMax",    g.xMax,    924),
        ("tri.yMax",    g.yMax,    924),
        ("head.xMin",   out["head"].xMin, 100),
        ("head.xMax",   out["head"].xMax, 924),
        ("glyphs_patched", n, 1),
    ]
    print()
    ok = True
    for label, got, want in asserts:
        passed = got == want
        ok = ok and passed
        print(f"  {'OK ' if passed else 'FAIL'}  {label:<14}= {got!r:<8}  (want {want!r})")
    for f in (src, dst):
        if os.path.exists(f):
            os.remove(f)
    sys.exit(0 if ok else 1)


if __name__ == "__main__":
    main()